const folioData   = $('Extraer Folio + Hashear1').first().json;
const folioLookup = $('Buscar Folio en Airtable1').first().json;
const config      = $("Buscar Config Programa1").first().json; // viene de Buscar Config Programa

// fbc: usar el guardado en Airtable (viene directo de la landing, más preciso)
// fallback: construirlo desde fbclid + timestamp
const storedFbc = folioLookup.fbc || null;
const fbclid    = folioLookup.fbclid || null;
const airtableTs = folioLookup.Timestamp || null;
const fbc = storedFbc ||
            (fbclid ? `fb.1.${airtableTs || Date.now()}.${fbclid}` : null);

// user_data con todas las señales disponibles
const user_data_obj = {
  ph: [folioData.hashed_phone],
  fn: [folioData.hashed_fn],
  ln: [folioData.hashed_ln],
};

if (fbc)                         user_data_obj.fbc                = fbc;
if (folioLookup.fbp)             user_data_obj.fbp                = folioLookup.fbp;
if (folioLookup.user_agent)      user_data_obj.client_user_agent  = folioLookup.user_agent;
if (folioLookup.ip) {
  // x-forwarded-for puede traer múltiples IPs separadas por coma — tomar la primera
  user_data_obj.client_ip_address = folioLookup.ip.split(',')[0].trim();
}

// event_source_url: Landing URL real > default_url del programa
const event_source_url = folioLookup['Landing URL'] || config.default_url || '';

return [{
  json: {
    folio:            folioData.folio,
    programa:         folioData.programa,
    event_time:       folioData.event_time,
    user_data_obj,
    pixel_id:         config.pixel_id,
    access_token:     config.access_token,
    event_source_url,
  }
}];

