  json: {
    folio:          folioMatch[1],
    programa:       progMatch[1].toUpperCase(),
    hashed_phone:   sha256(phone),
    hashed_fn:      sha256(first_name),
    hashed_ln:      sha256(last_name),
    event_time:     Math.floor(Date.now() / 1000),
    whatsapp_phone: whatsapp_phone,
    first_name:     first_name,
    last_name:      last_name,
  }
}];

