// Leer campos: soporta estructura plana (mapped) o anidada (raw webhook)
const data = $input.item.json;
const body = data.body || {};
const cf   = body.custom_fields || {};

const msg            = data.respuesta_definitiva || cf.respuesta_definitiva || '';
const whatsapp_phone = data.whatsapp_phone       || body.whatsapp_phone    || '';
const first_name     = data.first_name           || body.first_name        || '';
const last_name      = data.last_name            || body.last_name         || '';

// Formato compacto: [FFFFFF_PP] o [FFFFFF_PPP]
// Folio: 6 chars [A-Z0-9_-]; Programa: BS | BSG | HF | BSC
